steps.script:
var gs = tree.root.get_node("GameState")
var i = 0
for m in gs.state["units"]["U_CUSTODIAN_GUARD_B"]["models"]:
	m["position"] = {"x": 200.0 + i * 45.0, "y": 750.0}
	i += 1
gs.state["units"]["U_TELEMON_HEAVY_DREADNOUGHT_I"]["models"][0]["position"] = {"x": 880.0, "y": 1330.0}
return i

var gs = tree.root.get_node("GameState")
gs.state["meta"]["from_save"] = true
return tree.change_scene_to_file("res://scenes/Main.tscn")

var d = tree.root.get_node_or_null("TemptingTargetDialog")
if d != null:
	d.hide()
var r = tree.root.get_node_or_null("SecondaryMissionReviewDialog")
if r != null:
	r.hide()
var hp = tree.current_scene.get_node_or_null("GameLogPanel")
if hp != null:
	hp.visible = false
return true
